mapper.select:
SELECT COUNT(*) > 0
FROM agent_environment_variable_ref
WHERE tenant_id = #{tenantId}
  AND agent_version_id = #{agentVersionId}
  AND environment_variable_id = #{environmentVariableId}

mapper.delete:
DELETE FROM agent_environment_variable_ref
WHERE tenant_id = #{tenantId}
  AND agent_version_id = #{agentVersionId}
  AND environment_variable_id = #{environmentVariableId}

mapper.select:
SELECT ev.id, ev.name, ev.description, '**' AS `value`
FROM agent_environment_variable_ref ref
JOIN environment_variable ev
  ON ev.id = ref.environment_variable_id
 AND ev.tenant_id = #{tenantId}
 AND ev.is_deleted = 0
WHERE ref.tenant_id = #{tenantId}
  AND ref.agent_version_id = #{agentVersionId}
ORDER BY ev.name, ev.id

SELECT COUNT(*)
FROM agent_environment_variable_ref ref
LEFT JOIN environment_variable ev
  ON ev.id = ref.environment_variable_id
 AND ev.tenant_id = #{tenantId}
 AND ev.is_deleted = 0
WHERE ref.tenant_id = #{tenantId}
  AND ref.agent_version_id = #{agentVersionId}
  AND ev.id IS NULL
